#!/usr/bin/env python3
"""Generate tcl/pkgIndex.tcl (and the wheel-bundled copy).

Defaults match the CMake build (tkd2dcanvas 0.1, tkd2dcanvas01.dll).
"""
from __future__ import annotations

import argparse
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent

TEMPLATE = """# Tcl package index for {pkg}.
# Generated by tools/make_pkgindex.py — edit arguments, not this file.
package ifneeded {pkg} {version} \\
    [list load [file join $dir {lib}] {pkg}]
"""


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pkg", default="tkd2dcanvas")
    parser.add_argument("--version", default="0.1")
    parser.add_argument("--lib", default="tkd2dcanvas01.dll")
    parser.add_argument("--output", action="append", default=[],
                        help="Output file (repeatable). Default: tcl/pkgIndex.tcl and "
                             "python/tkd2dcanvas/tcl/<pkg>/pkgIndex.tcl")
    args = parser.parse_args()

    outputs = [Path(p) for p in args.output] or [
        REPO_ROOT / "tcl" / "pkgIndex.tcl",
        REPO_ROOT / "python" / "tkd2dcanvas" / "tcl" / args.pkg / "pkgIndex.tcl",
    ]

    content = TEMPLATE.format(pkg=args.pkg, version=args.version, lib=args.lib)
    for out in outputs:
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(content, encoding="utf-8")
        print(f"wrote {out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
